import{_ as a,o as t,c as i,a0 as l}from"./chunks/framework.BxrwG5q5.js";const p=JSON.parse('{"title":"Scheduling","description":"","frontmatter":{},"headers":[],"relativePath":"features/scheduling.md","filePath":"features/scheduling.md"}'),s={name:"features/scheduling.md"};function r(n,e,o,h,u,c){return t(),i("div",null,[...e[0]||(e[0]=[l(`<h1 id="scheduling" tabindex="-1">Scheduling <a class="header-anchor" href="#scheduling" aria-label="Permalink to &quot;Scheduling&quot;">​</a></h1><blockquote><p>See also: <a href="/config/features/targeting.html">Targeting Rules</a> · <a href="/config/features/prerequisites.html">Prerequisites</a> · <a href="/config/features/environments.html">Environments</a></p></blockquote><p>Schedule config changes to activate at a specific date and time. Perfect for planned launches, marketing campaigns, or timed feature releases. Schedules sit between overrides and <a href="/config/features/targeting.html">targeting rules</a> in the evaluation pipeline.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li>Open a config in the portal</li><li>Expand the <strong>Schedule</strong> section</li><li>Pick a date and time using the calendar picker</li><li>Set the target value (what the config should become at that time)</li><li>Save</li></ol><p>Once the scheduled time arrives, the API automatically returns the scheduled value instead of the default.</p><h2 id="schedule-behavior" tabindex="-1">Schedule Behavior <a class="header-anchor" href="#schedule-behavior" aria-label="Permalink to &quot;Schedule Behavior&quot;">​</a></h2><p>Schedules are <strong>one-shot activations</strong> — once the <code>activateAt</code> time is reached, the scheduled value becomes the resolved value permanently (until you change it or remove the schedule).</p><div class="info custom-block"><p class="custom-block-title">Schedules are permanent once activated</p><p>A schedule does NOT auto-revert. If the current time is past <code>activateAt</code>, the scheduled value is always returned. Think of it as &quot;switch to this value at this time, forever.&quot;</p></div><h3 id="what-happens-after-the-scheduled-time" tabindex="-1">What happens after the scheduled time? <a class="header-anchor" href="#what-happens-after-the-scheduled-time" aria-label="Permalink to &quot;What happens after the scheduled time?&quot;">​</a></h3><p>The evaluation logic is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (now &gt;= activateAt) → return targetValue</span></span>
<span class="line"><span>if (now &lt; activateAt) → skip, continue to targeting/rollout/default</span></span></code></pre></div><p>Once activated, the schedule takes precedence over targeting rules and rollouts indefinitely.</p><h2 id="time-limited-features-campaigns" tabindex="-1">Time-Limited Features (Campaigns) <a class="header-anchor" href="#time-limited-features-campaigns" aria-label="Permalink to &quot;Time-Limited Features (Campaigns)&quot;">​</a></h2><p>To enable a feature for a limited window (e.g., a 24-hour sale), use two config values:</p><ol><li><p><strong>Option A: Two schedules on separate flags</strong></p><ul><li><code>feature.sale_banner</code> — Schedule to <code>true</code> at sale start</li><li>After the sale ends, manually update the value back to <code>false</code> in the portal</li></ul></li><li><p><strong>Option B: Use targeting + schedule together</strong></p><ul><li>Schedule the flag to <code>true</code> at sale start</li><li>After the event, remove the schedule and the flag reverts to its default (<code>false</code>)</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Since schedules are permanent once activated, the recommended pattern for temporary features is to set a reminder to manually revert the flag or remove the schedule after your event ends. A future version may add schedule expiry.</p></div><h2 id="evaluation-priority" tabindex="-1">Evaluation Priority <a class="header-anchor" href="#evaluation-priority" aria-label="Permalink to &quot;Evaluation Priority&quot;">​</a></h2><p>Schedules sit between overrides and targeting in the pipeline:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Prerequisites → Overrides → Schedule → Targeting → Rollout → Default</span></span></code></pre></div><p>This means:</p><ul><li>User overrides still take priority over schedules</li><li>Schedules override <a href="/config/features/targeting.html">targeting rules</a> and <a href="/config/features/rollouts.html">rollout</a></li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Product launch</strong> — Enable a feature flag at midnight on launch day</li><li><strong>Sale pricing</strong> — Change a config value at the start of a sale event</li><li><strong>Gradual deprecation</strong> — Switch a value after a migration deadline</li><li><strong>Time-limited features</strong> — Combine with manual revert after the event</li></ul><h2 id="timezone" tabindex="-1">Timezone <a class="header-anchor" href="#timezone" aria-label="Permalink to &quot;Timezone&quot;">​</a></h2><p>Scheduled times are stored in UTC. The portal&#39;s calendar picker shows your local timezone. The API evaluates against the current UTC time.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/config/features/targeting.html">Targeting Rules</a> — Schedules override targeting in the evaluation pipeline</li><li><a href="/config/features/rollouts.html">Percentage Rollouts</a> — Combine with schedules for time-gated gradual rollouts</li><li><a href="/config/features/prerequisites.html">Prerequisites</a> — Prerequisites must pass before a schedule takes effect</li><li><a href="/config/features/audit-log.html">Audit Log</a> — Track when schedules were created and activated</li><li><a href="/config/features/environments.html">Environments</a> — Schedules are per-environment, enabling staged launches</li></ul>`,28)])])}const g=a(s,[["render",r]]);export{p as __pageData,g as default};
